<x-admin-layout>
    <div class="control-workspace" x-data="adminControl(@js([
        'snapshot' => route('admin.control.snapshot'), 'ask' => route('admin.control.ask'), 'clear' => route('admin.control.clear'),
        'sources' => ['admin.analytics' => route('admin.analytics'), 'admin.feedbacks.index' => route('admin.feedbacks.index'), 'admin.scraper' => route('admin.scraper'), 'admin.payments' => route('admin.payments')],
    ]))">
        <header class="control-heading">
            <div class="control-heading-copy"><h1>TraKerja Control</h1><p>Operations and business insights from your platform data.</p></div>
            <div class="control-toolbar"><span class="control-readonly"><i class="ph ph-eye" aria-hidden="true"></i> Analysis only</span><label for="control-period" class="sr-only">Analysis period</label><select id="control-period" x-model="days" @change="load()" :disabled="busy"><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select><button type="button" @click="load()" :disabled="busy || loading" class="control-icon-button" aria-label="Refresh operational snapshot"><i class="ph ph-arrow-clockwise" :class="loading && 'animate-spin'" aria-hidden="true"></i></button></div>
        </header>
        <div class="control-error" role="alert" x-show="error" x-cloak><i class="ph ph-warning-circle" aria-hidden="true"></i><span x-text="error"></span><button type="button" @click="load()" :disabled="busy">Reload data</button></div>
        <div class="control-layout">
            <aside class="control-rail" aria-label="Analysis workspaces">
                <p class="control-section-label">Choose an analysis</p>
                <nav class="control-modes"><template x-for="(mode, index) in modes" :key="mode.key"><button type="button" @click="choose(mode)" :class="{ 'is-active': focus === mode.key }" :aria-pressed="focus === mode.key" :disabled="busy"><i class="control-mode-index" :class="mode.icon" aria-hidden="true"></i><span><strong x-text="mode.label"></strong><small x-text="mode.description"></small></span><i class="ph ph-caret-right" aria-hidden="true"></i></button></template></nav>
            </aside>
            <div class="control-main">
                <section class="control-briefing" aria-labelledby="control-brief-title">
                    <header class="control-panel-heading"><div><p class="control-section-label">Operational briefing</p><h2 id="control-brief-title">Platform overview</h2></div><span class="control-snapshot-stamp" x-text="snapshot ? 'Updated ' + time(snapshot.generated_at) : 'Loading snapshot…'"></span></header>
                    <div class="control-metrics" :aria-busy="loading">
                        <div><span>New members</span><strong x-text="loading || !snapshot ? '—' : number(metrics.new_members)"></strong><small x-text="snapshot ? delta(metrics.new_members, metrics.previous_new_members) : 'Reading member records'"></small></div>
                        <div><span>Recorded revenue</span><strong class="control-money" x-text="loading || !snapshot ? '—' : money(metrics.revenue)"></strong><small x-text="snapshot ? delta(metrics.revenue, metrics.previous_revenue) : 'Reading settled payments'"></small></div>
                        <div><span>Pending support</span><strong x-text="loading || !snapshot ? '—' : number(metrics.pending_tickets)"></strong><small x-text="snapshot ? number(metrics.aged_tickets) + ' older than 48 hours' : 'Reading support backlog'"></small></div>
                    </div>
                    <div class="control-priorities"><div class="control-inline-heading"><h3>What deserves attention</h3><span>Rule-based priorities</span></div><p x-show="loading" role="status" class="control-loading">Building your operational snapshot…</p><template x-for="(item, index) in snapshot?.priorities || []" :key="item.area"><a :href="destination(item.route)" class="control-priority"><span class="control-priority-number" x-text="String(index + 1).padStart(2, '0')"></span><div><span class="control-priority-area" x-text="item.area"></span><h4 x-text="item.title"></h4><p x-text="item.evidence"></p></div><i class="ph ph-arrow-up-right" aria-hidden="true"></i></a></template></div>
                </section>
                <section class="control-conversation" aria-labelledby="control-analysis-title">
                    <header class="control-analysis-heading"><div><span class="control-analyst-mark" aria-hidden="true"><i class="ph ph-chart-line"></i></span><h2 id="control-analysis-title">Analysis desk</h2></div><div><button type="button" @click="copy()" :disabled="!messages.length || busy" x-text="copied ? 'Copied' : 'Copy latest'"></button><button type="button" @click="clear()" :disabled="!messages.length || busy">Clear conversation</button></div></header>
                    <div class="control-empty" x-show="!messages.length && !busy"><span class="control-empty-symbol" aria-hidden="true"><i class="ph ph-strategy"></i></span><h3>What would you like to investigate?</h3><p>Start with a briefing, or ask something specific about growth, payments, support, or scraper performance.</p><div class="control-starters"><button type="button" @click="choose(modes[0])">What should I focus on today?</button><button type="button" @click="choose(modes[1])">Where is member momentum changing?</button></div></div>
                    <div class="control-messages" aria-live="polite" aria-relevant="additions"><template x-for="(message, index) in messages" :key="index"><article class="control-message" :class="message.role === 'user' ? 'control-message-user' : 'control-message-analyst'"><header><strong x-text="message.role === 'user' ? 'You' : 'Control'"></strong><span x-text="message.role === 'model' ? (message.mode === 'ai' ? 'AI analysis · ' : 'Snapshot briefing · ') + time(message.at) : time(message.at)"></span></header><div class="control-message-content" x-show="message.role === 'user'" x-text="message.text"></div><div class="control-message-content control-answer" x-show="message.role === 'model'" x-html="formatAnswer(message.text)"></div></article></template><div class="control-thinking" x-show="busy" role="status"><span></span> Working with your platform snapshot…</div><span x-ref="latest"></span></div>
                    <form class="control-composer" @submit.prevent="ask()"><label for="control-question">What would you like to understand?</label><textarea id="control-question" x-ref="composer" x-model="prompt" maxlength="2000" rows="3" placeholder="Compare revenue and member growth. What should we investigate next?" :disabled="busy" @keydown.ctrl.enter.prevent="ask()" @keydown.meta.enter.prevent="ask()" aria-describedby="control-composer-help"></textarea><footer><span id="control-composer-help">Replies in Bahasa Indonesia<br><span class="control-shortcut">Ctrl / ⌘ + Enter to analyze</span></span><button type="submit" :disabled="busy || loading || prompt.trim().length < 3"><span x-text="busy ? 'Analyzing…' : 'Analyze'"></span><i class="ph ph-arrow-up-right" aria-hidden="true"></i></button></footer></form>
                </section>
            </div>
            <aside class="control-context" aria-label="Snapshot context and data sources">
                <section class="control-context-card"><header><h2>Context window</h2><span x-text="snapshot ? snapshot.period_label : 'Loading…'"></span></header><div class="control-trend"><div class="control-inline-heading"><h3>Registrations</h3><span x-text="days + ' days'"></span></div><div class="control-bars" role="img" aria-label="Daily member registrations; daily values are available in the table below"><template x-for="day in snapshot?.registrations || []" :key="day.label"><div :title="day.label + ': ' + day.count + ' registrations'"><span :style="{height: Math.max(3, day.count / highestRegistration * 100) + '%'}"></span></div></template></div><details class="control-trend-table"><summary>Daily values</summary><table><caption class="sr-only">Daily member registrations</caption><thead><tr><th>Date</th><th>Members</th></tr></thead><tbody><template x-for="day in snapshot?.registrations || []" :key="day.label"><tr><td x-text="day.label"></td><td x-text="number(day.count)"></td></tr></template></tbody></table></details></div><dl class="control-context-values"><div><dt>Active in period</dt><dd x-text="loading || !snapshot ? '—' : number(metrics.active_members)"></dd></div><div><dt>Active Premium share</dt><dd x-text="loading || !snapshot ? '—' : metrics.premium_share + '%'"></dd></div><div><dt>Applications created</dt><dd x-text="loading || !snapshot ? '—' : number(metrics.applications)"></dd></div><div><dt>Successful extractions</dt><dd x-text="loading || !snapshot ? '—' : number(metrics.scrape_successes)"></dd></div><div><dt>Failed extractions</dt><dd x-text="loading || !snapshot ? '—' : number(metrics.scrape_failures)"></dd></div></dl></section>
                <section class="control-context-card control-sources"><header><h2>Grounded in your data</h2><span>Snapshot definitions</span></header><template x-for="source in snapshot?.sources || []" :key="source.table"><details><summary x-text="source.label"></summary><p x-text="source.definition"></p><code x-text="source.table"></code></details></template><p class="control-context-note">Data is refreshed on each analysis. A snapshot explains what happened; it does not establish why.</p></section>
            </aside>
        </div>
    </div>
</x-admin-layout>
